const DEFAULTS = { sound: true, volume: 5 };
const soundBox = document.querySelector("#sound");
const volumeSelect = document.querySelector("#volume");

function loadSettings() {
  // kaydı oku, varsayılanlarla birleştir
  const saved = JSON.parse(localStorage.getItem("settings")) ?? {};
  return { ...DEFAULTS, ...saved };
}

// yükle, kutulara yerleştir, change olaylarında kaydet
const settings = loadSettings();

function saveSettings() {
  localStorage.setItem("settings", JSON.stringify(settings));
}

soundBox.checked = settings.sound;
volumeSelect.value = String(settings.volume);

soundBox.addEventListener("change", () => {
  settings.sound = soundBox.checked;
  saveSettings();
});
volumeSelect.addEventListener("change", () => {
  settings.volume = Number(volumeSelect.value);
  saveSettings();
});

check.js:
assert($("#sound").checked === true, "Kayıtta ses bilgisi yok; varsayılan (true) kullanılmalı, onay kutusu işaretli olmalı.");
assert($("#volume").value === "8", "Kayıtlı ses düzeyi (8) listede seçili olmalı.");
$("#sound").checked = false;
$("#sound").dispatchEvent(new Event("change", { bubbles: true }));
let saved = JSON.parse(localStorage.getItem("settings"));
assert(saved.sound === false && saved.volume === 8, "Onay kutusu değişince ayarlar ({ sound: false, volume: 8 }) kaydedilmeli.");
type("#volume", "3");
saved = JSON.parse(localStorage.getItem("settings"));
assert(saved.volume === 3 && saved.sound === false, "Ses düzeyi değişince sayı olarak (3) kaydedilmeli.");
localStorage.removeItem("settings");
const d = loadSettings();
assert(d.sound === true && d.volume === 5, "Kayıt yokken loadSettings() varsayılanları döndürmeli.");
localStorage.setItem("settings", '{"sound":false}');
const m = loadSettings();
assert(m.sound === false && m.volume === 5, "Eksik alanlar varsayılanla doldurulmalı ({ sound: false, volume: 5 }).");

