const feedback = document.querySelector("#feedback");

function loadRecord() {
  // quizRecord kaydını JSON.parse ile oku; yoksa { name: "-", score: 0 }
  const saved = localStorage.getItem("quizRecord");
  return saved ? JSON.parse(saved) : { name: "-", score: 0 };
}

function showRecord() {
  const record = loadRecord();
  document.querySelector("#best").textContent = `${record.score} (${record.name})`;
}

function finishQuiz(name, score) {
  // rekor kırıldıysa kaydet ve "Yeni rekor: 60!", değilse "Rekor: 40 (Ada). Tekrar dene!"
  const record = loadRecord();
  if (score > record.score) {
    localStorage.setItem("quizRecord", JSON.stringify({ name: name, score: score }));
    feedback.textContent = `Yeni rekor: ${score}!`;
  } else {
    feedback.textContent = `Rekor: ${record.score} (${record.name}). Tekrar dene!`;
  }
  showRecord();
}

showRecord();

check.js:
assert($("#best").textContent === "40 (Ada)", "Açılışta kayıtlı rekor #best'te '40 (Ada)' olarak görünmeli.");
finishQuiz("Efe", 30);
const kept = JSON.parse(localStorage.getItem("quizRecord"));
assert(kept.name === "Ada" && kept.score === 40, "Rekordan düşük skor kaydı değiştirmemeli.");
assert($("#feedback").textContent === "Rekor: 40 (Ada). Tekrar dene!", "Düşük skorda #feedback 'Rekor: 40 (Ada). Tekrar dene!' olmalı.");
finishQuiz("Efe", 60);
const rec = JSON.parse(localStorage.getItem("quizRecord"));
assert(rec.name === "Efe" && rec.score === 60, "Rekor kırılınca { name: 'Efe', score: 60 } JSON olarak kaydedilmeli.");
assert($("#feedback").textContent === "Yeni rekor: 60!" && $("#best").textContent === "60 (Efe)", "Rekorda 'Yeni rekor: 60!' yazmalı ve #best '60 (Efe)' olmalı.");
localStorage.removeItem("quizRecord");
const empty = loadRecord();
assert(empty.name === "-" && empty.score === 0, "Kayıt yokken loadRecord() { name: '-', score: 0 } döndürmeli.");
